/* Environment geometry: wall, floor, ceiling, ground, dressing            */
/* ---------------------------------------------------------------------- */

const envGroup = new THREE.Group();
scene.add(envGroup);

// Dividing wall
const wallMatIn = physMat(0xede6da, { roughness: 0.85, clearcoat: 0.05 });
const wallMatOut = physMat(0xcfc6b4, { roughness: 0.92, clearcoat: 0.0 });
const wallGeo = new THREE.BoxGeometry(WALL_X1 - WALL_X0, WALL_Y1 - WALL_Y0, WALL_THICK);
const wallMats = [wallMatOut, wallMatOut, wallMatOut, wallMatOut, wallMatIn, wallMatOut];
const wall = new THREE.Mesh(wallGeo, wallMats);
wall.position.set((WALL_X0 + WALL_X1) / 2, (WALL_Y0 + WALL_Y1) / 2, 0);
wall.receiveShadow = true; wall.castShadow = true;
envGroup.add(wall);

// baseboard trim (interior)
const baseboardMat = physMat(0xffffff, { roughness: 0.5 });
const baseboard = new THREE.Mesh(new THREE.BoxGeometry(WALL_X1 - WALL_X0, 0.09, 0.02), baseboardMat);
baseboard.position.set((WALL_X0 + WALL_X1) / 2, 0.045, WALL_Z_IN + 0.011);
envGroup.add(baseboard);

// Interior floor (wood planks)
const floorGroup = new THREE.Group();
const plankCount = 16;
const roomDepth = 6.4;
for (let i = 0; i < plankCount; i++) {
  const shade = 0.52 + Math.random() * 0.1;
  const plankMat = stdMat(new THREE.Color(shade * 0.62, shade * 0.42, shade * 0.28), { roughness: 0.62, metalness: 0.02 });
  const plank = new THREE.Mesh(new THREE.BoxGeometry(WALL_X1 - WALL_X0, 0.03, roomDepth / plankCount - 0.01), plankMat);
  plank.position.set((WALL_X0 + WALL_X1) / 2, -0.015, WALL_Z_IN + roomDepth / plankCount * (i + 0.5));
  plank.receiveShadow = true;
  floorGroup.add(plank);
}
envGroup.add(floorGroup);

// Interior ceiling
const ceiling = new THREE.Mesh(new THREE.BoxGeometry(WALL_X1 - WALL_X0, 0.05, roomDepth), physMat(0xf5f2ec, { roughness: 0.9 }));
ceiling.position.set((WALL_X0 + WALL_X1) / 2, WALL_Y1 + 0.025, WALL_Z_IN + roomDepth / 2);
envGroup.add(ceiling);

// ceiling light fixture
const ceilingLightMat = new THREE.MeshStandardMaterial({ color: 0xfff4dd, emissive: 0xfff0d0, emissiveIntensity: 1.3, roughness: 0.4 });
const ceilingLightFixture = new THREE.Mesh(new THREE.CircleGeometry(0.26, 24), ceilingLightMat);
ceilingLightFixture.rotation.x = Math.PI / 2;
ceilingLightFixture.position.set(0.4, WALL_Y1 - 0.01, 2.0);
envGroup.add(ceilingLightFixture);

// Side wall (corner, for depth)
const sideWall = new THREE.Mesh(new THREE.BoxGeometry(WALL_THICK, WALL_Y1 - WALL_Y0, roomDepth + WALL_THICK), wallMatIn);

